// Input 0..N-1: ShoppingList rows, last item: Settings row (merged combineAll puts them sequentially per input branch)
const listRows = $('Get Current List').all().map(i => i.json);
const settings = $('Get Settings').first().json;
const storeRows = $('Get Stores').all().map(i => i.json);

const total = listRows.reduce((sum, r) => sum + (Number(r.price) || 0) * (Number(r.qty) || 0), 0);
const budget = Number(settings.budget) || 0;

// Delivery fees: charged once per distinct store on the list that has a nonzero
// delivery_fee in the Stores tab -- flat fee only for v1, no free-delivery-above-$X
// threshold modeling yet (see household-ledger-sheets-schema.md Stores tab note).
const storesUsed = [...new Set(listRows.map(r => r.store).filter(Boolean))];
const deliveryFees = storesUsed
  .map(storeName => {
    const match = storeRows.find(s => s.store === storeName);
    return { store: storeName, fee: match ? Number(match.delivery_fee) || 0 : 0 };
  })
  .filter(d => d.fee > 0);
const deliveryTotal = Math.round(deliveryFees.reduce((sum, d) => sum + d.fee, 0) * 100) / 100;
const grandTotal = Math.round((total + deliveryTotal) * 100) / 100;

// Voice commands: Validate Voice Command only ran for a voice-triggered request,
// so this stays null for every other action -- never invents a reply.
let voiceReply = null;
try {
  const v = $('Validate Voice Command').first().json;
  if (v.intent === 'add') {
    voiceReply = v.matchedCatalog
      ? `Added ${v.item}${v.qty > 1 ? ` (x${v.qty})` : ''}.`
      : `Couldn't find ${v.item} in the catalog \u2014 try Browse Catalog or scan a receipt to add it with a real price.`;
  } else if (v.intent === 'remove') {
    voiceReply = `Removed ${v.item}.`;
  } else if (v.intent === 'clear') {
    voiceReply = 'Cleared the list.';
  } else if (v.intent === 'finalize') {
    voiceReply = 'List saved.';
  } else if (v.intent === 'price_check') {
    voiceReply = v.priceCheckReply || `No price found for ${v.item}.`;
  } else {
    voiceReply = "Sorry, I didn't catch that \u2014 try again.";
  }
} catch (e) {}

let barcodeResult = null;
try {
  if ($('List Webhook').first().json.body.action === 'barcode') {
    try {
      barcodeResult = $('Shape Catalog Barcode Result').first().json.barcodeResult;
    } catch (e) {
      barcodeResult = $('Shape External Barcode Result').first().json.barcodeResult;
    }
  }
} catch (e) {}

return [{
  json: {
    list: listRows,
    total: Math.round(total * 100) / 100,
    deliveryFees,
    deliveryTotal,
    grandTotal,
    budget,
    remaining: Math.round((budget - grandTotal) * 100) / 100,
    cadence: settings.cadence,
    stores: storeRows,
    voiceReply, barcodeResult
  }
}];

// Filters out only the alwaysOutputData synthetic placeholder (no row_number --
// it doesn't correspond to a real sheet row at all). A genuine blank/stray row
// still has a real row_number and must still count toward deletion, or Clear
// leaves it (and whatever real row follows it) behind -- found live 2026-08-09
// when a stray blank row 2 in ShoppingList caused exactly that.
const items = $input.all().filter((i) => i.json && i.json.row_number !== undefined);
return [{ json: { count: items.length } }];

const data = $input.first().json;
const list = data.list || [];
const lines = list.map(i => `• ${i.item} — $${Number(i.price).toFixed(2)}`).join('
');
const deliveryLine = data.deliveryTotal > 0
  ? `
Delivery: $${Number(data.deliveryTotal).toFixed(2)} (${(data.deliveryFees || []).map(d => d.store).join(', ')})`
  : '';
const text = `📋 Shopping list saved (${data.cadence || ''}):
${lines}

Items: $${Number(data.total).toFixed(2)}${deliveryLine}
Total: $${Number(data.grandTotal).toFixed(2)}
Budget: $${Number(data.budget).toFixed(2)}
Remaining: $${Number(data.remaining).toFixed(2)}`;
return [{ json: { text } }];

// Filters out only the alwaysOutputData synthetic placeholder (no row_number --
// it doesn't correspond to a real sheet row at all). A genuine blank/stray row
// still has a real row_number and must still count toward deletion, or Clear
// leaves it (and whatever real row follows it) behind -- found live 2026-08-09
// when a stray blank row 2 in ShoppingList caused exactly that.
const items = $input.all().filter((i) => i.json && i.json.row_number !== undefined);
return [{ json: { count: items.length } }];

// Rebuilds the finalized list as one item per row for appending to LastSavedList.
// Named reference back to Is Finalize? (not bare $json) because this node sits
// downstream of the Clear LastSavedList Rows/count sub-chain, which has replaced
// $json with row-count data by this point -- same wrong-payload-level bug class
// fixed elsewhere in this project.
const list = ($('Is Finalize?').first().json.list || []).filter((r) => r && r.item);
const today = $now.toFormat('yyyy-MM-dd');
return list.map((r) => ({
  json: {
    item: r.item,
    category: r.category,
    store: r.store,
    price: r.price,
    qty: r.qty,
    cadence: r.cadence,
    added_date: today
  }
}));

// Builds the prompt for Parse Voice Command via LLM -- the actual product catalog
// is injected here so the LLM can fuzzy-match the spoken item name to an existing
// canonical entry (same "never invent a price" discipline as receipt extraction --
// an unmatched item gets flagged rather than added with a guessed price).
const transcript = ($('List Webhook').first().json.body.transcript || '').trim();
const catalogLines = $input.all()
  .map(i => i.json)
  .filter(r => r.item)
  .map(r => `${r.item} | ${r.category || ''} | ${r.store || ''} | ${r.price || ''}`)
  .join('\n');

const prompt = `You control a household shopping list app by voice. The user's spoken command, already transcribed, was: "${transcript}"

Here is the current product catalog (one row per item/store, format "item | category | store | price"):
${catalogLines}

Determine what the user wants and respond with ONLY a JSON object, no prose, no markdown fences:
{"intent": "add" | "remove" | "clear" | "finalize" | "price_check" | "unclear", "item": string|null, "qty": number|null}

- "add": adding an item to the shopping list. Match the spoken item to the closest catalog item name if a reasonable match exists (e.g. "milk" matches "Whole Milk"); if nothing reasonably matches, still return the item as spoken, cleaned up and capitalized. Extract a quantity if one was stated (e.g. "add two apples" -> qty 2); default qty to 1 if not stated.
- "remove": removing an item already on the list. Match to the closest catalog item name the same way.
- "clear": clearing/emptying the whole list.
- "finalize": saving/finalizing the list for the week.
- "price_check": asking about an item's price or comparing prices. Match to the closest catalog item name.
- "unclear": you can't confidently tell what they want.

If any field doesn't apply to the determined intent, use null for it rather than guessing.`;

return [{ json: { transcript, prompt } }];

// Parses the LLM's voice-command JSON, resolves it against the real catalog data
// for 'add'/'price_check' (never trust the LLM's own price math -- same discipline
// as Validate Extraction), and defaults to 'unclear' on any parse failure so a
// malformed response never silently mutates the list.
let parsed;
try {
  let raw = $input.first().json.content?.find((b) => b.type === 'text')?.text ?? '';
  raw = raw.trim().replace(/^```(?:json)?\s*/, '').replace(/```\s*$/, '');
  parsed = JSON.parse(raw);
} catch (e) {
  return [{ json: { intent: 'unclear', item: null, qty: null, matchedCatalog: false } }];
}

const validIntents = ['add', 'remove', 'clear', 'finalize', 'price_check', 'unclear'];
const intent = validIntents.includes(parsed.intent) ? parsed.intent : 'unclear';
const item = typeof parsed.item === 'string' && parsed.item.length > 0 ? parsed.item : null;
const qty = (typeof parsed.qty === 'number' && parsed.qty > 0) ? Math.round(parsed.qty) : 1;

const catalogRows = $('Get Catalog for Voice').all().map(i => i.json).filter(r => r.item);

let matchedCatalog = false;
let category = 'Household';
let store = null;
let price = null;
let priceCheckReply = null;

if (item && (intent === 'add' || intent === 'price_check')) {
  const matches = catalogRows.filter((r) => r.item === item);
  if (matches.length > 0) {
    matchedCatalog = true;
    const cheapest = matches.reduce((a, b) => (Number(b.price) < Number(a.price) ? b : a));
    category = cheapest.category || 'Household';
    store = cheapest.store;
    price = Number(cheapest.price);
    if (intent === 'price_check') {
      const lines = matches.map((r) => `${r.store}: $${Number(r.price).toFixed(2)}`).join(', ');
      priceCheckReply = `${item} \u2014 ${lines}`;
    }
  } else if (intent === 'price_check') {
    priceCheckReply = `No price found for ${item}.`;
  }
}

return [{ json: { intent, item, qty, matchedCatalog, category, store, price, priceCheckReply } }];

// Reshapes the resolved voice 'add' command into the same { body: {...} } shape
// Upsert List Row already expects from a real webhook POST, so the existing node
// can be reused unchanged for both regular app upserts and voice-triggered ones.
const v = $('Validate Voice Command').first().json;
return [{ json: { body: {
  item: v.item,
  category: v.category,
  store: v.store,
  price: v.price,
  qty: v.qty,
  cadence: 'Week'
} } }];

// Reshapes the resolved voice 'remove' command into the same { body: { item } }
// shape Find Row to Remove already expects from a real webhook POST.
const v = $('Validate Voice Command').first().json;
return [{ json: { body: { item: v.item } } }];

// Matches the scanned barcode against real Catalog rows first -- instant, free,
// trusted. Only falls back to an external lookup (Shape External Barcode Result)
// when nothing here matches.
const barcode = String($('List Webhook').first().json.body.barcode || '').trim();
const rows = $input.all().map(i => i.json).filter(r => r.item && String(r.barcode || '').trim() === barcode);
return [{ json: { barcode, matches: rows } }];

// Real Catalog data -- trusted prices, no external call needed.
const barcode = $json.barcode;
const rows = $json.matches;
const item = rows[0]?.item || null;
const offers = rows.map(r => ({ store: r.store, price: Number(r.price) }))
  .sort((a, b) => a.price - b.price);
return [{ json: { barcodeResult: {
  source: 'catalog',
  matchedCatalog: true,
  barcode,
  item,
  offers
} } }];

// UPCitemdb trial tier: no key, ~100 lookups/day, coverage inconsistent -- treat as
// unverified/live data, never merge into Catalog automatically (no write-back).
const barcode = $('Match Barcode').first().json.barcode;
let item = null;
let offers = [];
let found = false;
try {
  const body = $json;
  const rec = body.items && body.items[0];
  if (rec) {
    found = true;
    item = rec.title || rec.brand || null;
    offers = (rec.offers || [])
      .filter((o) => o.price)
      .map((o) => ({ store: o.merchant || 'Unknown seller', price: Number(o.price) }))
      .sort((a, b) => a.price - b.price);
  }
} catch (e) {}
return [{ json: { barcodeResult: {
  source: 'external',
  matchedCatalog: false,
  barcode,
  item,
  offers,
  found
} } }];

const res = $json;
let address = null;
if (res && res.status === 'OK' && Array.isArray(res.results) && res.results.length > 0) {
  address = res.results[0].formatted_address || null;
}
return [{ json: { address } }];
